/*
 * A394733  A sequence constructed by greedily sampling the Hermite
 *          distribution, with both parameters as 1, to minimize discrepancy.
 *          The distribution indexing is adjusted to be strictly decreasing
 *          and support all positive integers.
 * https://oeis.org/A394733
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by greedily sampling the Hermite distribution
 *            (λ = μ = 1) conditioned on being ≥ 2 and subtracting 1. The
 *            sequence is produced by repeatedly choosing the integer k that
 *            maximises f(k)=n*p(k)-c(k), where c(k) is the number of
 *            occurrences of k in the already generated prefix and p...
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <math.h>
#include <stdint.h>

#define K_LIMIT 300          /* maximum k considered (sufficient for n≤10000) */
#define FACT_SIZE (K_LIMIT + 10)

/* memoised data */
static seq_t *seq = NULL;           /* generated sequence */
static size_t seq_len = 0, seq_cap = 0;

static unsigned long long count_arr[K_LIMIT + 1] = {0};   /* occurrence counts */
static long double pdist[K_LIMIT + 1] = {0.0L};          /* probabilities p(k) */
static long double fact[FACT_SIZE] = {0.0L};             /* factorials */

static long double p_factor = 0.0L;   /* exp(2) - 2, common denominator */
static bool initialized = false;

/* initialise factorials, probabilities and constant factors once */
static void init_once(void) {
    if (initialized) return;
    initialized = true;

    /* factorials */
    fact[0] = 1.0L;
    for (int i = 1; i < FACT_SIZE; ++i) fact[i] = fact[i - 1] * (long double)i;

    /* common denominator exp(2)-2 */
    p_factor = expl(2.0L) - 2.0L;

    /* probabilities p(k) for k = 1 .. K_LIMIT */
    for (int k = 1; k <= K_LIMIT; ++k) {
        int max_i = (k + 1) / 2;   /* ceil(k/2) */
        long double sum = 0.0L;
        for (int i = 0; i <= max_i; ++i) {
            int denom_part = k + 1 - 2 * i;
            sum += 1.0L / (fact[i] * fact[denom_part]);
        }
        pdist[k] = sum / p_factor;   /* p(k) */
    }

    /* initial allocation for the sequence buffer */
    seq_cap = 16;
    seq = (seq_t *)malloc(seq_cap * sizeof(seq_t));
}

/* Greedy generation of a(n) up to the requested index */
seq_t a(idx_t n) {
    init_once();

    /* generate more terms if necessary */
    while (seq_len < n) {
        idx_t current = seq_len + 1;          /* current n (1‑based) */

        /* find k with maximal f(k) = n*p(k) - c(k) */
        int best_k = 1;
        long double best_val = -1e300L;        /* very small negative */

        /* scan all k from 1 to K_LIMIT */
        for (int k = 1; k <= K_LIMIT; ++k) {
            long double val = (long double)current * pdist[k]
                              - (long double)count_arr[k];
            if (val > best_val) {
                best_val = val;
                best_k = k;
            }
        }

        /* append best_k to the sequence */
        if (seq_len >= seq_cap) {
            seq_cap *= 2;
            seq = (seq_t *)realloc(seq, seq_cap * sizeof(seq_t));
        }
        seq[seq_len] = (seq_t)best_k;
        seq_len++;

        /* update occurrence count */
        count_arr[best_k]++;
    }

    return seq[n - 1];
}
